+/* ===== RESET & BASE ===== */
+*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
+
+:root {
+  --clr-bg: #f8f7f4;
+  --clr-surface: #ffffff;
+  --clr-primary: #1a1a1a;
+  --clr-secondary: #5c5c5c;
+  --clr-accent: #e8490f;
+  --clr-accent-light: #fff0eb;
+  --clr-muted: #e5e3de;
+  --clr-deal: #0b6e4f;
+  --clr-deal-bg: #e8f5f0;
+  --radius-sm: 8px;
+  --radius-md: 14px;
+  --radius-lg: 20px;
+  --shadow-sm: 0 1px 4px rgba(0,0,0,.07);
