+button { cursor: pointer; font-family: inherit; border: none; background: none; }
+
+.container {
+  max-width: var(--max-w);
+  margin: 0 auto;
+  padding: 0 24px;
+}
+
+/* ===== TOPBAR ===== */
+.topbar {
+  background: var(--clr-primary);
+  color: #fff;
+  text-align: center;
+  font-size: .78rem;
+  letter-spacing: .04em;
+  padding: 9px 24px;
+}
+
+/* ===== HEADER / NAV ===== */
+.site-header {
+  background: var(--clr-surface);
+  border-bottom: 1px solid var(--clr-muted);
