+  font-size: .85rem;
+  font-weight: 600;
+  transition: background var(--transition), transform var(--transition);
+  white-space: nowrap;
+}
+.nav-cta:hover { background: #333; transform: translateY(-1px); }
+
+/* ===== HERO ===== */
+.hero {
