+}
+.hero-product-card .prod-name { font-size: 1rem; font-weight: 700; margin-bottom: 4px; }
+.hero-product-card .prod-price { font-size: 1.25rem; font-weight: 800; }
+.hero-product-card .prod-sub { font-size: .75rem; color: rgba(255,255,255,.5); margin-top: 2px; }
