+  opacity: .5;
+  user-select: none;
+}
+
+/* ===== SECTION HEADERS ===== */
+.section-header {
+  display: flex;
+  align-items: flex-end;
+  justify-content: space-between;
+  margin-bottom: 32px;
+  gap: 16px;
+}
+.section-label {
+  font-size: .72rem;
+  font-weight: 700;
