+
+.deal-body {
+  padding: 20px 22px;
+  flex: 1;
+  display: flex;
+  flex-direction: column;
+}
+
+.deal-badge {
+  display: inline-flex;
+  align-items: center;
+  gap: 5px;
+  background: var(--clr-deal-bg);
+  color: var(--clr-deal);
