+  font-weight: 700;
+  letter-spacing: .05em;
+  text-transform: uppercase;
+  padding: 4px 10px;
+  border-radius: 40px;
+  margin-bottom: 12px;
+  width: fit-content;
+}
+.deal-card.featured .deal-badge {
+  background: rgba(232,73,15,.2);
+  color: #ff8c65;
+}
+
+.deal-title {
+  font-size: 1rem;
+  font-weight: 700;
+  line-height: 1.35;
+  margin-bottom: 8px;
+}
+.deal-card.featured .deal-title { font-size: 1.3rem; }
+
+.deal-desc {
+  font-size: .82rem;
+  color: var(--clr-secondary);
+  margin-bottom: 16px;
+  line-height: 1.55;
+}
+.deal-card.featured .deal-desc { color: rgba(255,255,255,.55); }
+
+.deal-pricing {
+  display: flex;
