.shape-2 { width: 180px; height: 180px; bottom: 60px; right: 60px; }
.shape-3 { width: 100px; height: 100px; top: 160px; right: 200px; }

/* hero product images grid */
.hero-products-grid {
  position: absolute;
  inset: 0;
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-template-rows: 1fr 1fr;
  gap: 2px;
}
.hero-grid-cell {
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #2a2a2a;
}
.hero-grid-cell:nth-child(1) { background: #2e2e2e; }
.hero-grid-cell:nth-child(2) { background: #363636; }
.hero-grid-cell:nth-child(3) { background: #323232; }
.hero-grid-cell:nth-child(4) { background: #2c2c2c; }

.product-placeholder {
  font-size: 4rem;
  opacity: .5;
  user-select: none;
}

/* ===== SECTION HEADERS ===== */
.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 32px;
  gap: 16px;
}
.section-label {
  font-size: .72rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--clr-accent);
  margin-bottom: 6px;
}
.section-title {
  font-size: clamp(1.4rem, 2.5vw, 1.9rem);
  font-weight: 800;
  letter-spacing: -.02em;
  line-height: 1.2;
}
.section-desc {
  font-size: .9rem;
  color: var(--clr-secondary);
  margin-top: 6px;
  max-width: 520px;
}
.view-all {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: .85rem;
  font-weight: 600;
  color: var(--clr-accent);
  white-space: nowrap;
  transition: gap var(--transition);
}
.view-all:hover { gap: 10px; }

/* ===== CATEGORY STRIP ===== */
.categories { padding: 48px 0; }
.category-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 14px;
}
.cat-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 20px 12px;
  background: var(--clr-surface);
  border-radius: var(--radius-md);
  border: 1.5px solid var(--clr-muted);
  cursor: pointer;
  transition: border-color var(--transition), box-shadow var(--transition), transform var(--transition);
}
.cat-card:hover {
  border-color: var(--clr-primary);
  box-shadow: var(--shadow-md);
  transform: translateY(-3px);
}
.cat-icon {
  width: 52px; height: 52px;
  background: var(--clr-bg);
  border-radius: var(--radius-sm);
  display: flex; align-items: center; justify-content: center;
  font-size: 1.6rem;
}
.cat-name {
  font-size: .78rem;
  font-weight: 600;
  text-align: center;
  letter-spacing: -.01em;
}

/* ===== DEALS SECTION ===== */
.deals { padding: 56px 0; }

.deals-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  gap: 20px;
}

.deal-card {
  background: var(--clr-surface);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: box-shadow var(--transition), transform var(--transition);
  cursor: pointer;
  display: flex;
  flex-direction: column;
}
.deal-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.deal-card.featured {
  grid-row: span 2;
  background: linear-gradient(160deg, #1a1a1a 0%, #2d2d2d 100%);
  color: #fff;
}

.deal-image {
  height: 200px;
  background: var(--clr-bg);
  display: flex; align-items: center; justify-content: center;
  font-size: 4rem;
  flex-shrink: 0;
}
.deal-card.featured .deal-image { height: 300px; background: rgba(255,255,255,.05); }

.deal-body {
  padding: 20px 22px;
  flex: 1;
  display: flex;
  flex-direction: column;
}

.deal-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  background: var(--clr-deal-bg);
  color: var(--clr-deal);
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .05em;
  text-transform: uppercase;
  padding: 4px 10px;
  border-radius: 40px;
  margin-bottom: 12px;
  width: fit-content;
}
.deal-card.featured .deal-badge {
  background: rgba(232,73,15,.2);
  color: #ff8c65;
}

.deal-title {
  font-size: 1rem;
  font-weight: 700;
  line-height: 1.35;
  margin-bottom: 8px;
}
.deal-card.featured .deal-title { font-size: 1.3rem; }

.deal-desc {
  font-size: .82rem;
  color: var(--clr-secondary);
  margin-bottom: 16px;
  line-height: 1.55;
}
.deal-card.featured .deal-desc { color: rgba(255,255,255,.55); }

.deal-pricing {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: auto;
  flex-wrap: wrap;
}
.deal-price { font-size: 1.25rem; font-weight: 800; }
.deal-original {
  font-size: .85rem;
  color: var(--clr-secondary);
  text-decoration: line-through;
}
.deal-card.featured .deal-original { color: rgba(255,255,255,.35); }
.deal-save {
  background: var(--clr-accent);
  color: #fff;
  font-size: .7rem;
  font-weight: 700;
  padding: 3px 8px;
  border-radius: 40px;
}

.deal-timer {
  display: flex;
  gap: 8px;
  margin-top: 16px;
}
.timer-unit {
  display: flex; flex-direction: column; align-items: center;
  background: rgba(255,255,255,.08);
  border-radius: var(--radius-sm);
  padding: 8px 12px;
  min-width: 52px;
}
.timer-num { font-size: 1.1rem; font-weight: 800; }
.timer-label { font-size: .6rem; letter-spacing: .06em; opacity: .6; text-transform: uppercase; }

/* ===== FEATURED PRODUCTS ===== */
.featured { padding: 56px 0; }

.products-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.product-card {
  background: var(--clr-surface);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  border: 1.5px solid var(--clr-muted);
  transition: box-shadow var(--transition), transform var(--transition), border-color var(--transition);
  cursor: pointer;
  position: relative;
}
.product-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-4px);
  border-color: transparent;
}

.product-card-badge {
  position: absolute;
  top: 14px; left: 14px;
  z-index: 2;
  font-size: .68rem;
  font-weight: 700;
  letter-spacing: .05em;
  text-transform: uppercase;
  padding: 4px 10px;
  border-radius: 40px;
}
.badge-new { background: var(--clr-primary); color: #fff; }
.badge-sale { background: var(--clr-accent); color: #fff; }
.badge-hot { background: #f0a500; color: #fff; }

.product-wish {
  position: absolute;
  top: 12px; right: 12px;
  z-index: 2;
  width: 34px; height: 34px;
  background: rgba(255,255,255,.9);
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: 1rem;
  transition: background var(--transition), transform var(--transition);
  box-shadow: var(--shadow-sm);
}
.product-wish:hover { background: #fff; transform: scale(1.1); }
.product-wish.active { color: #e53e3e; }

.product-img {
  height: 220px;
  background: var(--clr-bg);
  display: flex; align-items: center; justify-content: center;
  font-size: 5rem;
  position: relative;
  overflow: hidden;
}
.product-img-overlay {
  position: absolute;
  inset: 0;
  background: rgba(0,0,0,.5);
  display: flex; align-items: center; justify-content: center;
  opacity: 0;
  transition: opacity var(--transition);
}
.product-card:hover .product-img-overlay { opacity: 1; }
.quick-view-btn {
  background: #fff;
  color: var(--clr-primary);
  font-size: .8rem;
  font-weight: 700;
  padding: 10px 20px;
  border-radius: 40px;
  transition: transform var(--transition);
}
.quick-view-btn:hover { transform: scale(1.05); }

.product-body {
  padding: 16px 18px;
}
.product-brand {
  font-size: .7rem;
  font-weight: 600;
  letter-spacing: .07em;
  text-transform: uppercase;
  color: var(--clr-secondary);
  margin-bottom: 4px;
}
.product-name {
  font-size: .92rem;
  font-weight: 700;
  line-height: 1.35;
  margin-bottom: 8px;
}
.product-stars {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-bottom: 10px;
}
.stars { color: #f0a500; font-size: .85rem; letter-spacing: -1px; }
.review-count { font-size: .72rem; color: var(--clr-secondary); }

.product-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}
.product-price { font-size: 1.05rem; font-weight: 800; }
.product-price-old {
  font-size: .8rem;
  color: var(--clr-secondary);
  text-decoration: line-through;
}
.add-cart-btn {
  width: 36px; height: 36px;
  background: var(--clr-primary);
  color: #fff;
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: 1.1rem;
  transition: background var(--transition), transform var(--transition);
  flex-shrink: 0;
}
.add-cart-btn:hover { background: var(--clr-accent); transform: scale(1.1); }

/* ===== EDITORIAL / EDITORIAL GRID ===== */
.editorial { padding: 56px 0; }

.editorial-grid {
  display: grid;
  grid-template-columns: 1.6fr 1fr;
  grid-template-rows: auto auto;
  gap: 20px;
}

.edit-card {
  border-radius: var(--radius-lg);
  overflow: hidden;
  position: relative;
  cursor: pointer;
  background: #1a1a1a;
  min-height: 280px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  transition: box-shadow var(--transition);
}
.edit-card:hover { box-shadow: var(--shadow-lg); }
.edit-card.large { grid-row: span 2; min-height: 580px; }

.edit-bg {
  position: absolute;
  inset: 0;
  font-size: 8rem;
  display: flex; align-items: center; justify-content: center;
  opacity: .15;
  pointer-events: none;
  user-select: none;
}
.edit-card.large .edit-bg { font-size: 12rem; }

.edit-gradient {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,.82) 0%, rgba(0,0,0,.2) 50%, transparent 100%);
}

.edit-content {
  position: relative;
  z-index: 1;
  padding: 28px;
  color: #fff;
}
.edit-tag {
  display: inline-block;
  background: var(--clr-accent);
  color: #fff;
  font-size: .68rem;
  font-weight: 700;
  letter-spacing: .07em;
  text-transform: uppercase;
  padding: 4px 10px;
  border-radius: 40px;
  margin-bottom: 10px;
}
.edit-title {
  font-size: 1.15rem;
  font-weight: 800;
  line-height: 1.3;
  margin-bottom: 8px;
}
.edit-card.large .edit-title { font-size: 1.6rem; }
.edit-meta {
  font-size: .76rem;
  color: rgba(255,255,255,.55);
  display: flex; align-items: center; gap: 8px;
}
.edit-meta-dot { width: 3px; height: 3px; background: rgba(255,255,255,.4); border-radius: 50%; }

.edit-card:hover .edit-title { text-decoration: underline; text-underline-offset: 3px; }

/* row of small edits */
.editorial-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

/* ===== BANNER ===== */
.promo-banner {
  margin: 0 0 56px;
  background: linear-gradient(135deg, var(--clr-accent) 0%, #c9360a 100%);
  border-radius: var(--radius-lg);
  padding: 40px 52px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  overflow: hidden;
  position: relative;
  color: #fff;
}
.promo-banner::after {
  content: '';
  position: absolute;
  right: -60px; top: -60px;
  width: 300px; height: 300px;
  border-radius: 50%;
  background: rgba(255,255,255,.08);
}
.promo-banner::before {
  content: '';
  position: absolute;
  right: 80px; bottom: -80px;
  width: 200px; height: 200px;
  border-radius: 50%;
  background: rgba(255,255,255,.05);
}
.promo-text .eyebrow {
  font-size: .72rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  opacity: .75;
  margin-bottom: 8px;
}
.promo-text h2 {
  font-size: clamp(1.5rem, 3vw, 2.2rem);
  font-weight: 800;
  letter-spacing: -.02em;
  line-height: 1.15;
}
.promo-text p { opacity: .8; font-size: .9rem; margin-top: 8px; }
.promo-code-box {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-shrink: 0;
  z-index: 1;
}
.promo-code {
  background: rgba(255,255,255,.15);
  border: 1.5px dashed rgba(255,255,255,.5);
  border-radius: var(--radius-sm);
  padding: 12px 24px;
  font-size: 1.1rem;
  font-weight: 800;
  letter-spacing: .1em;
}
.btn-white {
  background: #fff;
  color: var(--clr-accent);
  padding: 13px 28px;
  border-radius: 40px;
  font-weight: 700;
  font-size: .9rem;
  transition: transform var(--transition), box-shadow var(--transition);
  white-space: nowrap;
}
.btn-white:hover { transform: translateY(-2px); box-shadow: 0 8px 20px rgba(0,0,0,.2); }

/* ===== BRANDS ===== */
.brands {
  padding: 40px 0 56px;
  border-top: 1px solid var(--clr-muted);
  border-bottom: 1px solid var(--clr-muted);
  margin-bottom: 56px;
}
.brands-label {
  text-align: center;
  font-size: .72rem;
  font-weight: 700;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: var(--clr-secondary);
  margin-bottom: 28px;
}
.brands-row {
  display: flex;
  align-items: center;
  justify-content: space-around;
  gap: 24px;
  flex-wrap: wrap;
}
.brand-item {
  font-size: 1rem;
  font-weight: 800;
  letter-spacing: -.02em;
  color: var(--clr-muted);
  transition: color var(--transition);
  cursor: pointer;
  text-transform: uppercase;
  letter-spacing: .04em;
}
.brand-item:hover { color: var(--clr-primary); }

/* ===== NEWSLETTER ===== */
.newsletter {
  padding: 64px 0;
}
.newsletter-inner {
  background: var(--clr-primary);
  border-radius: var(--radius-lg);
  padding: 56px 64px;
  display: flex;
  align-items: center;
  gap: 48px;
  overflow: hidden;
  position: relative;
}
.newsletter-inner::after {
  content: '✉';
  position: absolute;
  right: 60px;
  font-size: 12rem;
  opacity: .05;
  pointer-events: none;
}
.newsletter-text { flex: 1; color: #fff; }
.newsletter-text h2 {
  font-size: 1.7rem;
  font-weight: 800;
  letter-spacing: -.02em;
  margin-bottom: 10px;
}
.newsletter-text p { color: rgba(255,255,255,.6); font-size: .92rem; }
.newsletter-form {
  display: flex;
  gap: 10px;
  flex: 1;
  max-width: 440px;
  z-index: 1;
}
.newsletter-form input {
  flex: 1;
  padding: 14px 20px;
  border-radius: 40px;
  border: none;
  background: rgba(255,255,255,.1);
  color: #fff;
  font-size: .9rem;
  outline: none;
  transition: background var(--transition);
}
.newsletter-form input::placeholder { color: rgba(255,255,255,.4); }
.newsletter-form input:focus { background: rgba(255,255,255,.15); }

/* ===== FOOTER ===== */
.site-footer {
  background: var(--clr-primary);
  color: rgba(255,255,255,.7);
  padding: 56px 0 32px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.6fr repeat(3, 1fr);
  gap: 40px;
  margin-bottom: 48px;
}
.footer-brand .logo { color: #fff; font-size: 1.3rem; }
.footer-brand .logo span { color: var(--clr-accent); }
.footer-brand p { margin-top: 12px; font-size: .84rem; line-height: 1.7; max-width: 260px; }
.footer-socials { display: flex; gap: 10px; margin-top: 20px; }
.social-btn {
  width: 36px; height: 36px;
  background: rgba(255,255,255,.08);
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: .9rem;
  transition: background var(--transition);
  color: rgba(255,255,255,.7);
}
.social-btn:hover { background: rgba(255,255,255,.18); color: #fff; }
.footer-col h4 { color: #fff; font-size: .85rem; font-weight: 700; margin-bottom: 16px; letter-spacing: .02em; }
.footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 10px; }
.footer-col li a { font-size: .83rem; transition: color var(--transition); }
.footer-col li a:hover { color: #fff; }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,.1);
  padding-top: 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  font-size: .78rem;
}
.footer-payments { display: flex; gap: 8px; align-items: center; }
.payment-icon {
  background: rgba(255,255,255,.1);
  border-radius: 5px;
  padding: 4px 8px;
  font-size: .7rem;
  font-weight: 700;
  color: rgba(255,255,255,.7);
}

/* ===== CART DRAWER ===== */
.cart-overlay {
  position: fixed; inset: 0; background: rgba(0,0,0,.5);
  z-index: 200; opacity: 0; pointer-events: none;
  transition: opacity var(--transition);
}
.cart-overlay.open { opacity: 1; pointer-events: all; }

.cart-drawer {
  position: fixed; top: 0; right: -440px; bottom: 0;
  width: 420px; background: var(--clr-surface);
  z-index: 201; box-shadow: var(--shadow-lg);
  transition: right .3s cubic-bezier(.4,0,.2,1);
  display: flex; flex-direction: column;
}
.cart-drawer.open { right: 0; }

.cart-header {
  padding: 22px 24px;
  border-bottom: 1px solid var(--clr-muted);
  display: flex; align-items: center; justify-content: space-between;
}
.cart-header h3 { font-size: 1.1rem; font-weight: 800; }
.cart-close {
  width: 34px; height: 34px;
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: 1.1rem;
  transition: background var(--transition);
}
.cart-close:hover { background: var(--clr-muted); }

.cart-items { flex: 1; overflow-y: auto; padding: 20px 24px; display: flex; flex-direction: column; gap: 16px; }
.cart-empty { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 12px; padding: 40px; }
.cart-empty-icon { font-size: 3.5rem; opacity: .3; }
.cart-empty p { color: var(--clr-secondary); font-size: .9rem; }

.cart-item {
  display: flex; gap: 14px; align-items: flex-start;
  padding: 14px; background: var(--clr-bg);
  border-radius: var(--radius-sm);
}
.cart-item-img {
  width: 60px; height: 60px; border-radius: var(--radius-sm);
  background: var(--clr-muted);
  display: flex; align-items: center; justify-content: center;
  font-size: 1.8rem; flex-shrink: 0;
}
.cart-item-info { flex: 1; }
.cart-item-name { font-size: .88rem; font-weight: 600; margin-bottom: 2px; }
.cart-item-meta { font-size: .75rem; color: var(--clr-secondary); }
.cart-item-price { font-size: .95rem; font-weight: 800; margin-top: 6px; }
.cart-item-qty {
  display: flex; align-items: center; gap: 8px;
  margin-top: 8px;
}
.qty-btn {
  width: 26px; height: 26px;
  border: 1.5px solid var(--clr-muted);
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: .9rem; font-weight: 700;
  transition: border-color var(--transition), background var(--transition);
}
.qty-btn:hover { border-color: var(--clr-primary); background: var(--clr-muted); }
.qty-num { font-size: .85rem; font-weight: 700; min-width: 16px; text-align: center; }
.cart-item-remove { color: var(--clr-secondary); font-size: .75rem; margin-left: auto; cursor: pointer; }
.cart-item-remove:hover { color: var(--clr-accent); }

.cart-footer {
  border-top: 1px solid var(--clr-muted); padding: 20px 24px;
}
.cart-subtotal {
  display: flex; justify-content: space-between; align-items: center;
  margin-bottom: 8px; font-size: .9rem;
}
.cart-subtotal .amount { font-size: 1.2rem; font-weight: 800; }
.cart-note { font-size: .75rem; color: var(--clr-secondary); margin-bottom: 16px; }
.checkout-btn {
  width: 100%; padding: 15px;
  background: var(--clr-primary); color: #fff;
  border-radius: 40px; font-size: .95rem; font-weight: 700;
  transition: background var(--transition), transform var(--transition);
}
.checkout-btn:hover { background: #333; transform: translateY(-1px); }

/* ===== TOAST ===== */
.toast {
  position: fixed; bottom: 28px; left: 50%; transform: translateX(-50%) translateY(80px);
  background: var(--clr-primary); color: #fff;
  padding: 12px 24px; border-radius: 40px;
  font-size: .88rem; font-weight: 600;
  z-index: 300; opacity: 0;
  transition: transform .3s ease, opacity .3s ease;
  white-space: nowrap;
  display: flex; align-items: center; gap: 8px;
}
