const cartItems = [];

// ===== HELPERS =====
const $ = (sel) => document.querySelector(sel);
const $$ = (sel) => document.querySelectorAll(sel);
const fmt = (n) => `$${n.toFixed(2)}`;

function starsHTML(rating) {
  const full = Math.floor(rating);
  const half = rating % 1 >= 0.5 ? 1 : 0;
  const empty = 5 - full - half;
  return '★'.repeat(full) + (half ? '½' : '') + '☆'.repeat(empty);
}

// ===== COUNTDOWN TIMER =====
function updateTimer() {
  const now = new Date();
  const end = new Date();
  end.setHours(23, 59, 59, 999);
  const diff = end - now;
  const h = Math.floor(diff / 3600000);
  const m = Math.floor((diff % 3600000) / 60000);
  const s = Math.floor((diff % 60000) / 1000);
  const pad = (n) => String(n).padStart(2, '0');
  const el = $('#timer');
  if (el) {
    el.innerHTML = `
      <div class="timer-unit"><span class="timer-num">${pad(h)}</span><span class="timer-label">Hrs</span></div>
      <div class="timer-unit"><span class="timer-num">${pad(m)}</span><span class="timer-label">Min</span></div>
      <div class="timer-unit"><span class="timer-num">${pad(s)}</span><span class="timer-label">Sec</span></div>
    `;
  }
}

// ===== CART =====
function addToCart(productId) {
  const product = products.find(p => p.id === productId);
  const existing = cartItems.find(i => i.id === productId);
  if (existing) {
    existing.qty++;
  } else {
    cartItems.push({ ...product, qty: 1 });
  }
  updateCartUI();
  showToast(`✓ ${product.name} added to cart`);
  openCart();
}

function removeFromCart(productId) {
  const idx = cartItems.findIndex(i => i.id === productId);
  if (idx > -1) cartItems.splice(idx, 1);
  updateCartUI();
}

function changeQty(productId, delta) {
  const item = cartItems.find(i => i.id === productId);
  if (!item) return;
  item.qty += delta;
  if (item.qty < 1) { removeFromCart(productId); return; }
  updateCartUI();
}

function updateCartUI() {
  const total = cartItems.reduce((s, i) => s + i.qty, 0);
  const subtotal = cartItems.reduce((s, i) => s + i.qty * i.price, 0);

  // badge
  $$('.cart-badge').forEach(b => {
    b.textContent = total;
    b.style.display = total > 0 ? 'flex' : 'none';
  });

  // subtotal
  const subEl = $('#cart-subtotal');
  if (subEl) subEl.textContent = fmt(subtotal);

  // items
  const container = $('#cart-items');
  if (!container) return;

  if (cartItems.length === 0) {
    container.innerHTML = `
      <div class="cart-empty">
        <div class="cart-empty-icon">🛒</div>
        <p>Your cart is empty.</p>
      </div>`;
    return;
  }

  container.innerHTML = cartItems.map(item => `
    <div class="cart-item" data-id="${item.id}">
      <div class="cart-item-img">${item.emoji}</div>
      <div class="cart-item-info">
        <div class="cart-item-name">${item.name}</div>
        <div class="cart-item-meta">${item.brand}</div>
        <div class="cart-item-price">${fmt(item.price)}</div>
        <div class="cart-item-qty">
          <button class="qty-btn" onclick="changeQty(${item.id}, -1)">−</button>
          <span class="qty-num">${item.qty}</span>
          <button class="qty-btn" onclick="changeQty(${item.id}, 1)">+</button>
          <span class="cart-item-remove" onclick="removeFromCart(${item.id})">Remove</span>
        </div>
      </div>
    </div>
  `).join('');
}

function openCart() {
  $('#cart-drawer').classList.add('open');
  $('#cart-overlay').classList.add('open');
  document.body.style.overflow = 'hidden';
}

function closeCart() {
  $('#cart-drawer').classList.remove('open');
  $('#cart-overlay').classList.remove('open');
  document.body.style.overflow = '';
}

// ===== TOAST =====
let toastTimeout;
function showToast(msg) {
  const toast = $('#toast');
  toast.textContent = msg;
  toast.classList.add('show');
  clearTimeout(toastTimeout);
  toastTimeout = setTimeout(() => toast.classList.remove('show'), 2800);
}

// ===== WISHLIST =====
const wishlist = new Set();
function toggleWishlist(productId, btn) {
  if (wishlist.has(productId)) {
    wishlist.delete(productId);
    btn.classList.remove('active');
    btn.textContent = '♡';
  } else {
    wishlist.add(productId);
    btn.classList.add('active');
    btn.textContent = '♥';
    showToast('♥ Added to wishlist');
  }
}

// ===== RENDER PRODUCTS =====
function renderProducts() {
