function initSearch() {
  const input = $('#nav-search');
  if (!input) return;
  input.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' && input.value.trim()) {
      showToast(`🔍 Searching for "${input.value.trim()}"…`);
      input.value = '';
    }
  });
}

// ===== PROMO CODE COPY =====
function copyPromo() {
  navigator.clipboard?.writeText('WELCOME20').catch(() => {});
  showToast('📋 Code WELCOME20 copied!');
}

