  { id: 2, name: 'Merino Wool Crewneck', brand: 'Wool & Sons', price: 89, oldPrice: 120, rating: 4.5, reviews: 152, emoji: '🧥', badge: 'sale', color: '#edf2f7' },
  { id: 3, name: 'Ceramic Pour-Over Set', brand: 'Brewed', price: 64, oldPrice: null, rating: 4.9, reviews: 431, emoji: '☕', badge: 'hot', color: '#fff5eb' },
  { id: 4, name: 'Slim Fit Chinos', brand: 'Tailored', price: 72, oldPrice: 95, rating: 4.3, reviews: 198, emoji: '👖', badge: 'sale', color: '#f0f4f8' },
  { id: 5, name: 'Canvas Tote Bag', brand: 'Carry.All', price: 38, oldPrice: null, rating: 4.6, reviews: 317, emoji: '👜', badge: 'new', color: '#faf5ff' },
  { id: 6, name: 'Minimal Watch', brand: 'Horology', price: 245, oldPrice: 310, rating: 4.8, reviews: 89, emoji: '⌚', badge: 'sale', color: '#f7fafc' },
  { id: 7, name: 'Scented Soy Candle', brand: 'Glow', price: 28, oldPrice: null, rating: 4.7, reviews: 522, emoji: '🕯️', badge: 'hot', color: '#fffbeb' },
  { id: 8, name: 'Hardcover Journal', brand: 'Pencraft', price: 22, oldPrice: 30, rating: 4.4, reviews: 273, emoji: '📓', badge: 'sale', color: '#f0fff4' },
];

const cartItems = [];

// ===== HELPERS =====
const $ = (sel) => document.querySelector(sel);
const $$ = (sel) => document.querySelectorAll(sel);
const fmt = (n) => `$${n.toFixed(2)}`;

function starsHTML(rating) {
  const full = Math.floor(rating);
  const half = rating % 1 >= 0.5 ? 1 : 0;
  const empty = 5 - full - half;
  return '★'.repeat(full) + (half ? '½' : '') + '☆'.repeat(empty);
}

// ===== COUNTDOWN TIMER =====
function updateTimer() {
  const now = new Date();
  const end = new Date();
  end.setHours(23, 59, 59, 999);
  const diff = end - now;
  const h = Math.floor(diff / 3600000);
  const m = Math.floor((diff % 3600000) / 60000);
  const s = Math.floor((diff % 60000) / 1000);
  const pad = (n) => String(n).padStart(2, '0');
  const el = $('#timer');
  if (el) {
    el.innerHTML = `
      <div class="timer-unit"><span class="timer-num">${pad(h)}</span><span class="timer-label">Hrs</span></div>
      <div class="timer-unit"><span class="timer-num">${pad(m)}</span><span class="timer-label">Min</span></div>
      <div class="timer-unit"><span class="timer-num">${pad(s)}</span><span class="timer-label">Sec</span></div>
    `;
  }
}

// ===== CART =====
function addToCart(productId) {
  const product = products.find(p => p.id === productId);
  const existing = cartItems.find(i => i.id === productId);
  if (existing) {
    existing.qty++;
  } else {
    cartItems.push({ ...product, qty: 1 });
  }
  updateCartUI();
  showToast(`✓ ${product.name} added to cart`);
  openCart();
}

function removeFromCart(productId) {
  const idx = cartItems.findIndex(i => i.id === productId);
  if (idx > -1) cartItems.splice(idx, 1);
  updateCartUI();
}

function changeQty(productId, delta) {
  const item = cartItems.find(i => i.id === productId);
  if (!item) return;
  item.qty += delta;
  if (item.qty < 1) { removeFromCart(productId); return; }
  updateCartUI();
}

function updateCartUI() {
  const total = cartItems.reduce((s, i) => s + i.qty, 0);
  const subtotal = cartItems.reduce((s, i) => s + i.qty * i.price, 0);

  // badge
  $$('.cart-badge').forEach(b => {
    b.textContent = total;
    b.style.display = total > 0 ? 'flex' : 'none';
  });

  // subtotal
  const subEl = $('#cart-subtotal');
  if (subEl) subEl.textContent = fmt(subtotal);

  // items
  const container = $('#cart-items');
  if (!container) return;

  if (cartItems.length === 0) {
    container.innerHTML = `
      <div class="cart-empty">
        <div class="cart-empty-icon">🛒</div>
        <p>Your cart is empty.</p>
      </div>`;
    return;
  }

  container.innerHTML = cartItems.map(item => `
    <div class="cart-item" data-id="${item.id}">
      <div class="cart-item-img">${item.emoji}</div>
      <div class="cart-item-info">
        <div class="cart-item-name">${item.name}</div>
        <div class="cart-item-meta">${item.brand}</div>
        <div class="cart-item-price">${fmt(item.price)}</div>
        <div class="cart-item-qty">
          <button class="qty-btn" onclick="changeQty(${item.id}, -1)">−</button>
          <span class="qty-num">${item.qty}</span>
          <button class="qty-btn" onclick="changeQty(${item.id}, 1)">+</button>
          <span class="cart-item-remove" onclick="removeFromCart(${item.id})">Remove</span>
        </div>
      </div>
    </div>
  `).join('');
}

function openCart() {
  $('#cart-drawer').classList.add('open');
  $('#cart-overlay').classList.add('open');
  document.body.style.overflow = 'hidden';
}

function closeCart() {
  $('#cart-drawer').classList.remove('open');
  $('#cart-overlay').classList.remove('open');
  document.body.style.overflow = '';
}

// ===== TOAST =====
let toastTimeout;
function showToast(msg) {
  const toast = $('#toast');
  toast.textContent = msg;
  toast.classList.add('show');
  clearTimeout(toastTimeout);
  toastTimeout = setTimeout(() => toast.classList.remove('show'), 2800);
}

// ===== WISHLIST =====
const wishlist = new Set();
function toggleWishlist(productId, btn) {
  if (wishlist.has(productId)) {
    wishlist.delete(productId);
    btn.classList.remove('active');
    btn.textContent = '♡';
  } else {
    wishlist.add(productId);
    btn.classList.add('active');
    btn.textContent = '♥';
    showToast('♥ Added to wishlist');
  }
}

// ===== RENDER PRODUCTS =====
function renderProducts() {
  const grid = $('#products-grid');
  if (!grid) return;
  grid.innerHTML = products.map(p => `
    <div class="product-card" data-id="${p.id}">
      ${p.badge ? `<span class="product-card-badge badge-${p.badge}">${p.badge}</span>` : ''}
      <button class="product-wish" onclick="toggleWishlist(${p.id}, this)" aria-label="Wishlist">♡</button>
      <div class="product-img" style="background:${p.color}">
        ${p.emoji}
        <div class="product-img-overlay">
          <button class="quick-view-btn" onclick="event.stopPropagation(); showToast('Opening quick view…')">Quick View</button>
        </div>
      </div>
      <div class="product-body">
        <div class="product-brand">${p.brand}</div>
        <div class="product-name">${p.name}</div>
        <div class="product-stars">
          <span class="stars">${starsHTML(p.rating)}</span>
          <span class="review-count">(${p.reviews})</span>
        </div>
        <div class="product-footer">
          <div>
            <div class="product-price">${fmt(p.price)}</div>
            ${p.oldPrice ? `<div class="product-price-old">${fmt(p.oldPrice)}</div>` : ''}
          </div>
          <button class="add-cart-btn" onclick="addToCart(${p.id})" aria-label="Add to cart">+</button>
        </div>
      </div>
    </div>
  `).join('');
}

// ===== NEWSLETTER =====
function handleNewsletter(e) {
  e.preventDefault();
  const input = e.target.querySelector('input');
  if (input.value) {
    showToast('🎉 You\'re subscribed! 10% off code sent.');
    input.value = '';
  }
}

// ===== SCROLL TO TOP =====
function initScrollTop() {
  const btn = $('#scroll-top');
  window.addEventListener('scroll', () => {
    btn.classList.toggle('visible', window.scrollY > 400);
  });
  btn.addEventListener('click', () => window.scrollTo({ top: 0, behavior: 'smooth' }));
}

// ===== NAV SEARCH =====
function initSearch() {
  const input = $('#nav-search');
  if (!input) return;
  input.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' && input.value.trim()) {
      showToast(`🔍 Searching for "${input.value.trim()}"…`);
      input.value = '';
    }
  });
}

// ===== PROMO CODE COPY =====
function copyPromo() {
  navigator.clipboard?.writeText('WELCOME20').catch(() => {});
  showToast('📋 Code WELCOME20 copied!');
}

// ===== INIT =====
document.addEventListener('DOMContentLoaded', () => {
  renderProducts();
  updateCartUI();
  updateTimer();
  setInterval(updateTimer, 1000);
  initScrollTop();
  initSearch();

  // Cart toggle
  $('#cart-btn')?.addEventListener('click', openCart);
  $('#cart-overlay')?.addEventListener('click', closeCart);
  $('#cart-close')?.addEventListener('click', closeCart);

  // Newsletter
  $('#newsletter-form')?.addEventListener('submit', handleNewsletter);

  // Promo code click to copy
  $('#promo-code')?.addEventListener('click', copyPromo);

  // Smooth category clicks
  $$('.cat-card').forEach(card => {
    card.addEventListener('click', () => {
      const name = card.querySelector('.cat-name').textContent;
      showToast(`Browsing ${name}…`);
    });
  });
});
